"""Metadata filtering with a MongoDB/Chroma-like query language.

A filter is a dict. Bare values mean equality; lists mean ``$in``. Logical
operators may be nested.

Examples::

    {"category": "troubleshooting"}                       # equality
    {"category": ["api", "troubleshooting"]}              # $in
    {"year": {"$gte": 2023}}                              # comparison
    {"tags": {"$any": ["auth", "billing"]}}               # list-field overlap
    {"author": {"$exists": True}}
    {"summary": {"$contains": "webhook"}}                 # substring
    {"$and": [{"category": "api"}, {"year": {"$gte": 2023}}]}
    {"$or": [{"priority": {"$gte": 4}}, {"category": "release-notes"}]}
    {"$not": {"category": "product"}}

Supported comparison operators per field: ``$eq``, ``$ne``, ``$gt``, ``$gte``,
``$lt``, ``$lte``, ``$in``, ``$nin``, ``$contains``, ``$any``, ``$all``,
``$exists``, ``$regex``.
"""
from __future__ import annotations

import re
from typing import Any, Dict, List


class MetadataFilterError(ValueError):
    """Raised when a filter query is malformed."""


def _field_matches(value: Any, cond: Any) -> bool:
    """Evaluate a single field's condition against a metadata value."""
    if isinstance(cond, dict) and any(k.startswith("$") for k in cond):
        for op, operand in cond.items():
            if op == "$eq":
                if not (value == operand):
                    return False
            elif op == "$ne":
                if value == operand:
                    return False
            elif op == "$gt":
                if not (value is not None and value > operand):
                    return False
            elif op == "$gte":
                if not (value is not None and value >= operand):
                    return False
            elif op == "$lt":
                if not (value is not None and value < operand):
                    return False
            elif op == "$lte":
                if not (value is not None and value <= operand):
                    return False
            elif op == "$in":
                if value not in operand:
                    return False
            elif op == "$nin":
                if value in operand:
                    return False
            elif op == "$contains":
                if not (value is not None and operand in str(value)):
                    return False
            elif op == "$any":
                if not _overlaps(value, operand):
                    return False
            elif op == "$all":
                if not _contains_all(value, operand):
                    return False
            elif op == "$exists":
                if (value is not None) != bool(operand):
                    return False
            elif op == "$regex":
                if not (value is not None and re.search(operand, str(value))):
                    return False
            else:
                raise MetadataFilterError(f"Unsupported operator: {op!r}")
        return True

    if isinstance(cond, list):
        # A bare list means "$in".
        return value in cond
    return value == cond


def _overlaps(value: Any, operands: List[Any]) -> bool:
    """True if any operand is present in a scalar or list field value."""
    if value is None:
        return False
    values = value if isinstance(value, (list, tuple, set)) else [value]
    return any(item in values for item in operands)


def _contains_all(value: Any, operands: List[Any]) -> bool:
    """True if every operand is present in a scalar or list field value."""
    if value is None:
        return False
    values = value if isinstance(value, (list, tuple, set)) else [value]
    return all(item in values for item in operands)


def matches(metadata: Dict[str, Any], query: Any) -> bool:
    """Return True if ``metadata`` satisfies the filter ``query``."""
    if query is None:
        return True
    if not isinstance(query, dict):
        raise MetadataFilterError(f"Filter must be a dict, got {type(query).__name__}")
    for key, cond in query.items():
        if key == "$and":
            if not isinstance(cond, list) or not all(
                matches(metadata, sub) for sub in cond
            ):
                return False
        elif key == "$or":
            if not isinstance(cond, list) or not any(
                matches(metadata, sub) for sub in cond
            ):
                return False
        elif key == "$nor":
            if isinstance(cond, list) and any(matches(metadata, sub) for sub in cond):
                return False
        elif key == "$not":
            if matches(metadata, cond):
                return False
        else:
            if not _field_matches(metadata.get(key), cond):
                return False
    return True

"""Document chunking with metadata propagation.

* :class:`RecursiveCharacterTextSplitter` - separator-aware splitting with
  configurable overlap (the recommended default).
* :class:`TokenTextSplitter` - sentence-level splitting bounded by token count.
"""
from __future__ import annotations

import re
from typing import List, Optional, Sequence

from rag_metadata.models import Document
from rag_metadata.tokenizer import tokenize

DEFAULT_SEPARATORS = ["\n\n", "\n", " ", ""]


class RecursiveCharacterTextSplitter:
    """Split text recursively on progressively smaller separators.

    Metadata is copied onto every produced chunk so downstream filtering and
    ranking can use it.
    """

    def __init__(
        self,
        chunk_size: int = 1000,
        chunk_overlap: int = 200,
        separators: Optional[Sequence[str]] = None,
    ):
        if chunk_size < 1:
            raise ValueError("chunk_size must be >= 1")
        if chunk_overlap < 0:
            raise ValueError("chunk_overlap must be >= 0")
        if chunk_overlap >= chunk_size:
            raise ValueError("chunk_overlap must be < chunk_size")
        self.chunk_size = chunk_size
        self.chunk_overlap = chunk_overlap
        self.separators = list(separators) if separators else list(DEFAULT_SEPARATORS)

    def split_text(self, text: str) -> List[str]:
        return _split_recursive(text, self.chunk_size, self.chunk_overlap, self.separators)

    def split_documents(self, documents: Sequence[Document]) -> List[Document]:
        chunks: List[Document] = []
        for doc in documents:
            for text in self.split_text(doc.page_content):
                chunks.append(Document(page_content=text, metadata=dict(doc.metadata), id=doc.id))
        return chunks


def _find_separator(text: str, separators: Sequence[str]) -> Optional[str]:
    for sep in separators:
        if sep and sep in text:
            return sep
    return None


def _split_recursive(
    text: str, chunk_size: int, chunk_overlap: int, separators: Sequence[str]
) -> List[str]:
    if len(text) <= chunk_size:
        return [text]

    sep = _find_separator(text, separators)
    if sep is None:
        return _split_characters(text, chunk_size, chunk_overlap)

    pieces = text.split(sep)
    chunks: List[str] = []
    current = ""
    for piece in pieces:
        piece = piece.strip()
        if not piece:
            continue
        candidate = piece if not current else current + sep + piece
        if len(candidate) <= chunk_size:
            current = candidate
            continue
        if current:
            chunks.append(current)
        if len(piece) <= chunk_size:
            current = piece
        else:
            # Piece is still too big: recurse with the next separator level.
            current = ""
            chunks.extend(_split_recursive(piece, chunk_size, chunk_overlap, separators[1:]))
    if current:
        chunks.append(current)

    return _apply_overlap(chunks, chunk_overlap, sep)


def _split_characters(text: str, chunk_size: int, chunk_overlap: int) -> List[str]:
    chunks: List[str] = []
    start, n = 0, len(text)
    while start < n:
        end = min(start + chunk_size, n)
        chunks.append(text[start:end])
        if end == n:
            break
        start = max(end - chunk_overlap, start + 1)
    return chunks


def _apply_overlap(chunks: List[str], chunk_overlap: int, sep: str) -> List[str]:
    """Prepend the tail of each previous chunk to preserve context."""
    result: List[str] = []
    prev_tail = ""
    for chunk in chunks:
        if prev_tail:
            chunk = prev_tail + sep + chunk
        result.append(chunk)
        if len(chunk) > chunk_overlap:
            prev_tail = chunk[-chunk_overlap:]
        else:
            prev_tail = ""
    return result


class TokenTextSplitter:
    """Split on sentence boundaries, bounded by an approximate token count."""

    def __init__(self, chunk_size: int = 512, chunk_overlap: int = 50):
        if chunk_size < 1:
            raise ValueError("chunk_size must be >= 1")
        self.chunk_size = chunk_size
        self.chunk_overlap = chunk_overlap

    def split_text(self, text: str) -> List[str]:
        sentences = re.split(r"(?<=[.!?])\s+", text or "")
        chunks: List[str] = []
        current: List[str] = []
        current_tokens = 0
        for sentence in sentences:
            sentence = sentence.strip()
            if not sentence:
                continue
            tokens = len(tokenize(sentence))
            if current and current_tokens + tokens > self.chunk_size:
                chunks.append(" ".join(current))
                # Keep the last chunk_overlap tokens' worth of sentences.
                kept: List[str] = []
                kept_tokens = 0
                for kept_sentence in reversed(current):
                    kept_tokens += len(tokenize(kept_sentence))
                    kept.insert(0, kept_sentence)
                    if kept_tokens >= self.chunk_overlap:
                        break
                current = kept
                current_tokens = kept_tokens
            current.append(sentence)
            current_tokens += tokens
        if current:
            chunks.append(" ".join(current))
        return chunks

    def split_documents(self, documents: Sequence[Document]) -> List[Document]:
        chunks: List[Document] = []
        for doc in documents:
            for text in self.split_text(doc.page_content):
                chunks.append(Document(page_content=text, metadata=dict(doc.metadata), id=doc.id))
        return chunks

"""Embedding functions.

All implementations share the :class:`EmbeddingFunction` protocol so stores and
retrievers are pluggable.

Offline options (no API keys, no model downloads):
    * :class:`HashingEmbedding` - character n-gram hashing; instant, crude.
    * :class:`TfidfEmbedding` - corpus-fitted TF-IDF; better, still offline.

Quality options (optional dependencies):
    * :class:`SentenceTransformerEmbedding` - ``pip install sentence-transformers``
    * :class:`OpenAIEmbedding` - ``pip install openai`` + ``OPENAI_API_KEY``
"""
from __future__ import annotations

import hashlib
import math
import re
from collections import Counter
from typing import List, Protocol, Sequence, runtime_checkable

import numpy as np

from rag_metadata.tokenizer import tokenize


@runtime_checkable
class EmbeddingFunction(Protocol):
    """Protocol implemented by all embedding functions."""

    def embed_documents(self, texts: Sequence[str]) -> np.ndarray:
        """Return an (n, dim) float32 matrix (rows L2-normalized)."""
        ...

    def embed_query(self, text: str) -> np.ndarray:
        """Return a single (dim,) float32 vector (L2-normalized)."""
        ...


class HashingEmbedding:
    """Character n-gram hashing embedding.

    Fast, deterministic, and dependency-free. Useful for smoke tests and as a
    fallback when no embedding model is installed.
    """

    def __init__(self, dim: int = 512, ngram: int = 3):
        self.dim = dim
        self.ngram = ngram

    def _hash(self, token: str) -> int:
        return int(hashlib.md5(token.encode("utf-8")).hexdigest(), 16) % self.dim

    def embed_text(self, text: str) -> np.ndarray:
        vec = np.zeros(self.dim, dtype=np.float32)
        text = (text or "").lower()
        if len(text) < self.ngram:
            vec[self._hash(text)] += 1.0
        else:
            for i in range(len(text) - self.ngram + 1):
                vec[self._hash(text[i : i + self.ngram])] += 1.0
        norm = float(np.linalg.norm(vec))
        if norm > 0:
            vec /= norm
        return vec

    def embed_documents(self, texts: Sequence[str]) -> np.ndarray:
        return np.vstack([self.embed_text(t) for t in texts]).astype(np.float32)

    def embed_query(self, text: str) -> np.ndarray:
        return self.embed_text(text)


class TfidfEmbedding:
    """Corpus-fitted TF-IDF embedding (offline, sparse-ish dense vectors).

    Call :meth:`fit` once on the corpus before use. The vocabulary is bounded
    by ``max_features`` (most frequent tokens) to keep vectors compact.
    """

    def __init__(self, max_features: int = 8192, min_df: int = 1):
        self.max_features = max_features
        self.min_df = min_df
        self.vocab: dict = {}
        self.idf: dict = {}
        self._fitted = False

    def fit(self, texts: Sequence[str]) -> "TfidfEmbedding":
        tokenized = [tokenize(t) for t in texts]
        doc_freq: Counter = Counter()
        for toks in tokenized:
            for tok in set(toks):
                doc_freq[tok] += 1

        vocab = {
            tok: idx
            for idx, (tok, count) in enumerate(doc_freq.most_common(self.max_features))
            if count >= self.min_df
        }
        n_docs = max(len(texts), 1)
        self.vocab = vocab
        self.idf = {
            tok: math.log(1.0 + (n_docs - doc_freq[tok] + 0.5) / (doc_freq[tok] + 0.5))
            for tok in vocab
        }
        self._fitted = True
        return self

    def _check_fitted(self) -> None:
        if not self._fitted:
            raise RuntimeError("TfidfEmbedding.fit() must be called before use")

    def embed_text(self, text: str) -> np.ndarray:
        self._check_fitted()
        vec = np.zeros(len(self.vocab), dtype=np.float32)
        if not self.vocab:
            return vec
        for tok, count in Counter(tokenize(text)).items():
            idx = self.vocab.get(tok)
            if idx is not None:
                vec[idx] = count * self.idf[tok]
        norm = float(np.linalg.norm(vec))
        if norm > 0:
            vec /= norm
        return vec

    def embed_documents(self, texts: Sequence[str]) -> np.ndarray:
        return np.vstack([self.embed_text(t) for t in texts]).astype(np.float32)

    def embed_query(self, text: str) -> np.ndarray:
        return self.embed_text(text)


class SentenceTransformerEmbedding:
    """Wrapper around sentence-transformers models (e.g. all-MiniLM-L6-v2)."""

    def __init__(self, model_name: str = "all-MiniLM-L6-v2"):
        try:
            from sentence_transformers import SentenceTransformer
        except ImportError as exc:  # pragma: no cover - depends on env
            raise ImportError(
                "sentence-transformers is required for SentenceTransformerEmbedding. "
                "Install with: pip install sentence-transformers"
            ) from exc
        self.model = SentenceTransformer(model_name)

    def embed_documents(self, texts: Sequence[str]) -> np.ndarray:
        return self.model.encode(list(texts), normalize_embeddings=True).astype(np.float32)

    def embed_query(self, text: str) -> np.ndarray:
        return self.model.encode([text], normalize_embeddings=True).astype(np.float32)[0]


class OpenAIEmbedding:
    """Wrapper around OpenAI's text-embedding models."""

    def __init__(self, model: str = "text-embedding-ada-002", api_key: str | None = None):
        try:
            import openai
        except ImportError as exc:  # pragma: no cover - depends on env
            raise ImportError(
                "openai is required for OpenAIEmbedding. Install with: pip install openai"
            ) from exc
        self.client = openai.OpenAI(api_key=api_key)
        self.model = model

    def embed_documents(self, texts: Sequence[str]) -> np.ndarray:
        resp = self.client.embeddings.create(input=list(texts), model=self.model)
        return np.asarray([d.embedding for d in resp.data], dtype=np.float32)

    def embed_query(self, text: str) -> np.ndarray:
        return self.embed_documents([text])[0]

"""Rankers: re-rank retrieved documents using metadata preferences.

:class:`MetadataRanker` blends a document's retrieval relevance with a
metadata preference score::

    final = (1 - metadata_weight) * relevance + metadata_weight * metadata_score

Preference grammar::

    preferences = {
        "year":     {"mode": "top"},                       # higher year wins
        "priority": {"mode": "top"},
        "category": {"mode": "exact", "values": ["api"]},
        "tags":     {"mode": "contains", "values": ["auth"]},
        "rating":   {"mode": "range", "min": 4.0, "max": 5.0},
        "status":   {"mode": "exact", "values": ["active"], "weight": 2.0},
    }

Modes:
    * ``exact``    - 1.0 if the field value is in ``values`` else 0.0
    * ``contains`` - 1.0 if any of ``values`` appears in the field value
    * ``top``      - numeric field, min-max normalized (higher is better)
    * ``bottom``   - numeric field, min-max normalized (lower is better)
    * ``range``    - 1.0 if ``min <= value <= max`` else 0.0

``weight`` (default 1.0) controls each field's importance relative to others.
"""
from __future__ import annotations

from typing import List, Optional, Protocol

from rag_metadata.models import ScoredDocument
from rag_metadata.scoring import min_max_normalize


class Ranker(Protocol):
    """Protocol implemented by all rankers."""

    def rerank(self, query: str, candidates: List[ScoredDocument]) -> List[ScoredDocument]:
        ...


def _to_float(value) -> float:
    try:
        return float(value)
    except (TypeError, ValueError):
        return 0.0


class IdentityRanker:
    """No-op ranker."""

    def rerank(self, query: str, candidates: List[ScoredDocument]) -> List[ScoredDocument]:
        return candidates


class MetadataRanker:
    """Re-ranks candidates by blending relevance with metadata preferences."""

    def __init__(
        self,
        preferences: Optional[dict] = None,
        metadata_weight: float = 0.3,
    ):
        if not 0.0 <= metadata_weight <= 1.0:
            raise ValueError("metadata_weight must be within [0, 1]")
        self.preferences = preferences or {}
        self.metadata_weight = metadata_weight

    def rerank(self, query: str, candidates: List[ScoredDocument]) -> List[ScoredDocument]:
        if not candidates:
            return candidates

        # Pre-compute per-field preference scores across all candidates.
        field_scores: dict = {}
        for field, spec in self.preferences.items():
            mode = spec.get("mode", "exact")
            if mode in ("top", "bottom"):
                nums = [_to_float(c.document.metadata.get(field)) for c in candidates]
                normalized = min_max_normalize(nums)
                if mode == "bottom":
                    normalized = [1.0 - n for n in normalized]
                field_scores[field] = normalized
            else:
                field_scores[field] = [
                    self._field_score(c.document.metadata.get(field), spec)
                    for c in candidates
                ]

        total_weight = sum(
            float(spec.get("weight", 1.0)) for spec in self.preferences.values()
        ) or 1.0

        for i, candidate in enumerate(candidates):
            meta_score = 0.0
            for field, spec in self.preferences.items():
                w = float(spec.get("weight", 1.0))
                meta_score += w * field_scores[field][i]
            meta_score /= total_weight

            relevance = candidate.score
            final = (1.0 - self.metadata_weight) * relevance + self.metadata_weight * meta_score
            candidate.scores["relevance"] = relevance
            candidate.scores["metadata"] = meta_score
            candidate.scores["final"] = final
            candidate.score = final

        candidates.sort(key=lambda c: c.score, reverse=True)
        return candidates

    @staticmethod
    def _field_score(value, spec: dict) -> float:
        mode = spec.get("mode", "exact")
        if mode == "exact":
            return 1.0 if value in spec.get("values", []) else 0.0
        if mode == "contains":
            if value is None:
                return 0.0
            return 1.0 if any(v in str(value) for v in spec.get("values", [])) else 0.0
        if mode == "range":
            low = _to_float(spec.get("min", float("-inf")))
            high = _to_float(spec.get("max", float("inf")))
            v = _to_float(value)
            return 1.0 if low <= v <= high else 0.0
        raise ValueError(f"Unknown metadata ranker mode: {mode!r}")


class CrossEncoderRanker:
    """Optional neural re-ranker (``pip install sentence-transformers``)."""

    def __init__(self, model_name: str = "cross-encoder/ms-marco-MiniLM-L-6-v2"):
        try:
            from sentence_transformers import CrossEncoder
        except ImportError as exc:  # pragma: no cover - depends on env
            raise ImportError(
                "sentence-transformers is required for CrossEncoderRanker. "
                "Install with: pip install sentence-transformers"
            ) from exc
        self.model = CrossEncoder(model_name)

    def rerank(self, query: str, candidates: List[ScoredDocument]) -> List[ScoredDocument]:
        if not candidates:
            return candidates
        pairs = [(query, c.document.page_content) for c in candidates]
        scores = self.model.predict(pairs)
        for candidate, score in zip(candidates, scores):
            candidate.scores["cross_encoder"] = float(score)
            candidate.score = float(score)
        candidates.sort(key=lambda c: c.score, reverse=True)
        return candidates

"""Prompt templates for grounded, citation-aware answer generation."""

CITATION_PROMPT = """Answer the question based on the context below. Include citations using [1], [2], etc. If the answer cannot be determined from the context, say "I don't have enough information."

Context:
{context}

Question: {question}

Answer (with citations):"""


def format_context(scored_docs, max_chars: int | None = None) -> str:
    """Render retrieved documents as a numbered, metadata-annotated context."""
    parts = []
    for i, scored in enumerate(scored_docs, start=1):
        meta = scored.document.metadata
        meta_str = ", ".join(f"{key}={value}" for key, value in meta.items())
        content = scored.document.page_content
        if max_chars is not None and len(content) > max_chars:
            content = content[:max_chars] + "..."
        parts.append(f"[{i}] ({meta_str})\n{content}")
    return "\n\n".join(parts)

"""LLM adapters.

* :class:`LLM` - protocol every generator implements.
* :class:`DummyLLM` - offline stand-in; echoes the prompt so the pipeline can
  be exercised without network access.
* :class:`OpenAILLM` - optional real LLM (``pip install openai``).
"""
from __future__ import annotations

from typing import Protocol, runtime_checkable


@runtime_checkable
class LLM(Protocol):
    def generate(self, prompt: str) -> str:
        ...


class DummyLLM:
    """Offline stand-in that lets the pipeline run without an API key."""

    def generate(self, prompt: str) -> str:
        return (
            "[dummy-llm] No LLM configured. Install `openai` and pass OpenAILLM() "
            "to RAGPipeline for generative answers. Extractive answer below.\n\n"
            + prompt[:400]
        )


class OpenAILLM:
    """Chat-completions adapter for OpenAI models."""

    def __init__(
        self,
        model: str = "gpt-4o-mini",
        api_key: str | None = None,
        temperature: float = 0.0,
    ):
        try:
            import openai
        except ImportError as exc:  # pragma: no cover - depends on env
            raise ImportError(
                "openai is required for OpenAILLM. Install with: pip install openai"
            ) from exc
        self.client = openai.OpenAI(api_key=api_key)
        self.model = model
        self.temperature = temperature

    def generate(self, prompt: str) -> str:
        resp = self.client.chat.completions.create(
            model=self.model,
            messages=[{"role": "user", "content": prompt}],
            temperature=self.temperature,
        )
        return resp.choices[0].message.content.strip()

